def transform(grid):
    h, w = len(grid), len(grid[0])
    occupied = {
        (r, c)
        for r in range(h)
        for c in range(w)
        if grid[r][c] == 8
    }

    pieces = []
    for r in range(h - 1):
        for c in range(w - 1):
            square = {
                (r, c), (r, c + 1),
                (r + 1, c), (r + 1, c + 1)
            }

            # Complete 2x2 squares are color 1.
            if square <= occupied:
                pieces.append((frozenset(square), 1))

            # L-shaped pieces, with the missing corner determining color.
            orientations = [
                ((r, c), 2),         # missing top-left
                ((r, c + 1), 4),     # missing top-right
                ((r + 1, c), 3),     # missing bottom-left
            ]
            for missing, color in orientations:
                shape = square - {missing}
                if shape <= occupied:
                    pieces.append((frozenset(shape), color))

    by_cell = {p: [] for p in occupied}
    for shape, color in pieces:
        for p in shape:
            by_cell[p].append((shape, color))

    failed = set()

    def solve(remaining):
        remaining = frozenset(remaining)
        if not remaining:
            return ()
        if remaining in failed:
            return None

        # Cover the most constrained cell first.
        p = min(
            remaining,
            key=lambda q: sum(shape <= remaining for shape, _ in by_cell[q])
        )
        for shape, color in by_cell[p]:
            if shape <= remaining:
                rest = solve(remaining - shape)
                if rest is not None:
                    return ((shape, color),) + rest

        failed.add(remaining)
        return None

    tiling = solve(occupied)
    if tiling is None:
        return [[0 for _ in range(w)] for _ in range(h)]

    result = [[0] * w for _ in range(h)]
    for shape, color in tiling:
        for r, c in shape:
            result[r][c] = color
    return result
